# Export actual 32px coordinates as editable PIX2 in addition to runtime PNGs.
names=[n for n,im in assets.items() if im.size==(32,32)];cols=6;rows=(len(names)+cols-1)//cols
doc=['@pix2 1.1','@meta','  title: "Ember original props"','  version: "1.1"','  color_mode: "RGBA"','  coordinate_origin: "top-left"','@grid',f'  columns: {cols}',f'  rows: {rows}','  default_cell: 32x32','  background: none','@palette']+[f'  {i+1}: {c}' for i,c in enumerate(P)]
