for i,name in enumerate(names):
 im=assets[name];sheet.paste(im,(i%cols*32,i//cols*32));doc += [f'@cell {name}',f'  name: "{name}"',f'  grid_pos: {i//cols},{i%cols}',f'@layer {name}_layer',f'  cell: {name}',f'@region {name}_pixels',f'  cell: {name}',f'  parent: {name}_layer']
 for y in range(32):
  line=[]
  for x in range(32):
   c=im.getpixel((x,y))
   if c[3]:line.append(f'p {x},{y} {P.index("#%02x%02x%02x"%c[:3])+1}')
  if line:doc.append('  '+' '.join(line))
doc.append('@end');(out/'props.pix2').write_text('\n'.join(doc)+'\n');sheet.save(out/'props.png')
